import { fileURLToPath } from 'node:url';
import readline from 'node:readline/promises';
import {
  validateWorkflow,
  validateWorkflowAtGate,
  validatePr,
  countOpenBlockingQuestions,
  parseFrontMatterLoose,
  scopeDiffForTask,
  detectBaseRef,
  resolveTaskDir,
  scaffoldTask,
  REQUIRED_TASK_FILES,
  allRuleFiles,
  normalizeCommand,
  relativePosix,
  COMMANDS,
  modeBriefing,
  evaluateModeCompletion,
  appendRunLog,
  readRunLog,
  codesOf,
  buildReport,
  renderReport,
  validateSrsReference,
  validateQuestionsRouting,
  validatePlanArchitecture,
  validatePlanChecklistSync,
  validateInputSyncReport,
  validateFigmaEvidence,
  validateAssetGate,
  loadProjectConfig,
  findUntrackedSourceChanges,
  buildRetroData,
  renderRetroSummary,
  validateRetroFolder,
  exportUpstreamProposals,
  RETRO_ROOT,
} from '@frontend-delivery-kit/validators';

const __filename = fileURLToPath(import.meta.url);
// Cả bản nguồn (bin/) lẫn bản bundle (standalone/ trong kit, bin/ trong repo
// dự án) đều nằm đúng một cấp dưới thư mục gốc.
const kitRoot = path.resolve(path.dirname(__filename), '..');
// esbuild `define` thay hằng này khi bundle: bản copy trong repo dự án không
// được đọc package.json của dự án để lấy version kit.
const BUNDLED_VERSION = typeof __FE_KIT_VERSION__ !== 'undefined' ? __FE_KIT_VERSION__ : '';
const PLUGIN_ID = 'fe@frontend-delivery';
const MARKETPLACE_NAME = 'frontend-delivery';
const args = process.argv.slice(2);
const command = args[0] || 'help';
const AGENT_ORDER = ['codex', 'claude', 'cursor', 'github'];
const AGENT_ALIASES = {
  all: 'all',
  everything: 'all',
  codex: 'codex',
  openai: 'codex',
  agent: 'codex',
  agents: 'all',
  claude: 'claude',
  'claude-code': 'claude',
  cursor: 'cursor',
  github: 'github',
  copilot: 'github',
  'github-copilot': 'github',
  gh: 'github'
};
const AGENT_LABELS = {
  codex: 'Codex / OpenAI coding agents',
  claude: 'Claude Code',
  cursor: 'Cursor',
  github: 'GitHub Copilot'
};

function argValueFlexible(name, fallback = '') {
  const eq = args.find(a => a.startsWith(name + '='));
  if (eq) return eq.slice(name.length + 1);
  return argValue(name, fallback);
}

function normalizeAgents(raw) {
  const input = String(raw || '').trim();
  if (!input) return [];
  const numberMap = { '1': 'all', '2': 'codex', '3': 'claude', '4': 'cursor', '5': 'github' };
  const tokens = input.split(/[,+\s]+/).map(t => t.trim().toLowerCase()).filter(Boolean).map(t => numberMap[t] || t);
  const selected = new Set();
  for (const token of tokens) {
    const normalized = AGENT_ALIASES[token];
    if (!normalized) throw new Error('Unknown agent target: ' + token + '. Valid values: all, codex/openai, claude, cursor, github/copilot.');
    if (normalized === 'all') AGENT_ORDER.forEach(a => selected.add(a));
    else selected.add(normalized);
  }
  return AGENT_ORDER.filter(a => selected.has(a));
}

function explicitAgentsArg() {
  if (args.includes('--all-agents')) return 'all';
  return argValueFlexible('--agents', '') || argValueFlexible('--agent', '');
}

async function chooseAgentsForInit() {
  const explicit = explicitAgentsArg();
  if (explicit) return normalizeAgents(explicit);
  if (args.includes('--no-interactive') || args.includes('--yes') || args.includes('-y') || !process.stdin.isTTY) return normalizeAgents('all');
  console.log('Chọn agent target để cài vào project:');
  console.log('  1) all    - Codex/OpenAI + Claude Code + Cursor + GitHub Copilot');
  console.log('  2) codex  - AGENTS.md + .codex prompts');
  console.log('  3) claude - CLAUDE.md + .claude/rules + bật plugin fe trong .claude/settings.json');
  console.log('  4) cursor - .cursor rules');
  console.log('  5) github - GitHub Copilot instructions + PR template');
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  try {
    const answer = await rl.question('Nhập số/tên hoặc danh sách, ví dụ "claude,codex" [all]: ');
    return normalizeAgents(answer || 'all');
  } finally {
    rl.close();
  }
}

function readKitVersion() {
  if (BUNDLED_VERSION) return BUNDLED_VERSION;
  try {
    const pkg = JSON.parse(read(path.join(kitRoot, 'package.json')) || '{}');
    return pkg.version || 'unknown';
  } catch {
    return 'unknown';
  }
}

function installManifestPath(target) {
  return path.join(target, '.frontend-delivery', 'install.json');
}

function writeInstallManifest(target, agents) {
  const manifest = {
    kit: 'frontend-delivery-agent-kit',
    version: readKitVersion(),
    agents,
    installed_at: new Date().toISOString(),
    note: 'Generated by fe-kit init. Init ghi đè file do kit quản lý (.frontend-delivery/rules, templates, adapter rules) và giữ nguyên file của team (docs/frontend-context, phần ngoài khối fe-kit trong CLAUDE.md/AGENTS.md).'
  };
  const p = installManifestPath(target);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(manifest, null, 2) + '\n');
  const md = [
    '# Frontend Delivery Kit Install Manifest',
    '',
    'Version: ' + manifest.version,
    '',
    'Cache marker: vi-diacritics-rules-folder-v1.0.0', '', 'Rules folder: .frontend-delivery/rules/', '', 'Installed agents:',
    ...agents.map(a => '- ' + a + ': ' + AGENT_LABELS[a]),
    '',
    'To add agents later:',
    '',
    'node bin/fe-kit.mjs init --agents claude,codex,cursor,github',
    ''
  ].join('\n');
  fs.writeFileSync(path.join(target, '.frontend-delivery', 'agents.md'), md);
}

function readInstalledAgents(target) {
  const p = installManifestPath(target);
  if (!fs.existsSync(p)) return [];
  try {
    const data = JSON.parse(fs.readFileSync(p, 'utf8'));
    return normalizeAgents(Array.isArray(data.agents) ? data.agents.join(',') : data.agents);
  } catch {
    return [];
  }
}

function agentsForDoctor(target) {
  const explicit = explicitAgentsArg();
  if (explicit) return normalizeAgents(explicit);
  const installed = readInstalledAgents(target);
  return installed.length ? installed : normalizeAgents('all');
}

function agentList(agents) {
  return agents.map(a => a + ' (' + AGENT_LABELS[a] + ')').join(', ');
}


function argValue(name, fallback) {
  const i = args.indexOf(name);
  if (i >= 0 && args[i + 1]) return args[i + 1];
  return fallback;
}

function taskArg() {
  return args[1] || argValue('--task', '');
}

function copyDir(src, dest) {
  if (!fs.existsSync(src)) return;
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDir(s, d);
    else fs.copyFileSync(s, d);
  }
}

/** File do kit quản lý: luôn ghi đè để repo dự án nhận bản mới. */
function copyFile(src, dest) {
  if (!fs.existsSync(src)) return;
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
}

/** File của team: chỉ tạo khi chưa có. Trước v2.0.0 hàm này ghi đè vô điều kiện. */
function copyFileIfMissing(src, dest) {
  if (!fs.existsSync(src) || fs.existsSync(dest)) return false;
  copyFile(src, dest);
  return true;
}

/** Như copyDir nhưng không đụng file đã tồn tại (vd docs/frontend-context team đã điền). */
function copyDirIfMissing(src, dest) {
  if (!fs.existsSync(src)) return;
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDirIfMissing(s, d);
    else copyFileIfMissing(s, d);
  }
}

const BLOCK_START = '<!-- fe-kit:start (khối do fe-kit init quản lý, sửa ngoài khối này) -->';
const BLOCK_END = '<!-- fe-kit:end -->';

/**
 * Ghi nội dung của kit vào CLAUDE.md/AGENTS.md mà không xoá phần team tự viết:
 * file chưa có thì tạo, đã có khối fe-kit thì thay khối, chưa có khối thì nối vào cuối.
 */
function upsertManagedBlock(dest, content) {
  const block = `${BLOCK_START}\n${String(content).replace(/\r\n/g, '\n').trim()}\n${BLOCK_END}\n`;
  if (!fs.existsSync(dest)) {
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, block);
    return 'created';
  }
  const current = fs.readFileSync(dest, 'utf8');
  const start = current.indexOf(BLOCK_START);
  const end = current.indexOf(BLOCK_END);
  if (start >= 0 && end > start) {
    fs.writeFileSync(dest, current.slice(0, start) + block.trimEnd() + current.slice(end + BLOCK_END.length));
    return 'updated';
  }
  fs.writeFileSync(dest, current.replace(/\s*$/, '\n\n') + block);
  return 'appended';
}

function adapterPath(agent, ...rel) {
  return path.join(kitRoot, 'core', 'adapters', agent, ...rel);
}

const RUNLOG_GITATTRIBUTES = 'docs/frontend-tasks/**/tracking/run-log.jsonl merge=union';

/** Run-log chỉ nối thêm dòng: gộp nhánh bằng union để hai nhánh cùng ghi không conflict. */
function ensureRunLogMergeUnion(target) {
  const file = path.join(target, '.gitattributes');
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  if (current.split(/\r?\n/).some((line) => line.trim() === RUNLOG_GITATTRIBUTES)) return false;
  const prefix = current ? current.replace(/\s*$/, '\n') : '';
  fs.writeFileSync(file, `${prefix}# fe-kit: run-log chỉ nối thêm dòng, gộp nhánh không conflict\n${RUNLOG_GITATTRIBUTES}\n`);
  return true;
}

/** Tên lịch sử của prompt Codex khác tên lệnh ở 2 chỗ. */
const CODEX_PROMPT_NAME = { 'cook.md': 'build.md', 'figma.md': 'figma-extract.md' };

/** Sinh .codex/prompts từ core/commands: bỏ frontmatter của Claude, thêm heading `# FE <cmd>`. */
function writeCodexPrompts(target) {
  const srcDir = path.join(kitRoot, 'core', 'commands');
  if (!fs.existsSync(srcDir)) return 0;
  const destDir = path.join(target, '.codex', 'prompts');
  fs.rmSync(destDir, { recursive: true, force: true });
  fs.mkdirSync(destDir, { recursive: true });
  const files = fs.readdirSync(srcDir).filter((f) => f.endsWith('.md'));
  for (const f of files) {
    const raw = fs.readFileSync(path.join(srcDir, f), 'utf8').replace(/\r\n/g, '\n');
    const body = raw.replace(/^---\n[\s\S]*?\n---\n\n?/, '');
    fs.writeFileSync(path.join(destDir, CODEX_PROMPT_NAME[f] || f), `# FE ${f.replace(/\.md$/, '')}\n\n${body}`);
  }
  return files.length;
}

function marketplaceRepo() {
  const explicit = argValueFlexible('--marketplace-repo', '');
  if (explicit) return explicit;
  try {
    const plugin = JSON.parse(fs.readFileSync(path.join(kitRoot, 'core', 'plugin.json'), 'utf8'));
    const m = String(plugin.repository || '').match(/github\.com[:/]([^/]+\/[^/.\s]+)/);
    return m ? m[1] : '';
  } catch {
    return '';
  }
}

/**
 * Bật plugin `fe` cho repo dự án bằng cách merge vào .claude/settings.json.
 * Không ghi đè key khác; settings.json hỏng thì bỏ qua và báo.
 */
function enableClaudePlugin(target) {
  const file = path.join(target, '.claude', 'settings.json');
  let settings = {};
  if (fs.existsSync(file)) {
    try {
      settings = JSON.parse(fs.readFileSync(file, 'utf8'));
    } catch {
      console.warn(`Không parse được ${file}; hãy tự thêm enabledPlugins["${PLUGIN_ID}"] = true.`);
      return false;
    }
  }
  const repo = marketplaceRepo();
  settings.extraKnownMarketplaces ||= {};
  if (!settings.extraKnownMarketplaces[MARKETPLACE_NAME] && repo) {
    settings.extraKnownMarketplaces[MARKETPLACE_NAME] = { source: { source: 'github', repo } };
  }
  settings.enabledPlugins ||= {};
  settings.enabledPlugins[PLUGIN_ID] = true;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(settings, null, 2) + '\n');
  return true;
}

function claudePluginEnabled(target) {
  for (const name of ['settings.json', 'settings.local.json']) {
    try {
      const settings = JSON.parse(fs.readFileSync(path.join(target, '.claude', name), 'utf8'));
      if (settings.enabledPlugins?.[PLUGIN_ID] === true) return true;
    } catch { /* thiếu file hoặc JSON hỏng: coi như chưa bật */ }
  }
  return false;
}

/** Bản copy agents/commands/skill của v1.x: nếu còn sẽ xuất hiện trùng với plugin. */
function legacyClaudeCopies(target) {
  const found = [];
  for (const rel of ['.claude/commands/fe', '.claude/skills/frontend-delivery-standard']) {
    if (fs.existsSync(path.join(target, rel))) found.push(rel);
  }
  const agentsDir = path.join(target, '.claude', 'agents');
  if (fs.existsSync(agentsDir)) {
    for (const f of fs.readdirSync(agentsDir)) {
      if (/^frontend-(planner|developer|reviewer|tester|figma-specialist|release-manager)\.md$/.test(f)) found.push(`.claude/agents/${f}`);
    }
  }
  return found;
}

function read(relOrAbs) {
  const p = path.resolve(relOrAbs);
  if (!fs.existsSync(p)) return '';
  return fs.readFileSync(p, 'utf8');
}


// Parser YAML thật (gray-matter) dùng chung với validators. Bản regex cũ ở đây
// không đọc được file CRLF và giá trị chứa dấu `:`.
const parseFrontMatter = parseFrontMatterLoose;

function exists(p) { return fs.existsSync(p); }

function walk(dir, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(p, out);
    else out.push(p);
  }
  return out;
}

function resolveTask(input, target = process.cwd()) {
  if (!input) return '';
  const direct = path.resolve(input);
  if (fs.existsSync(direct)) return direct;
  const fromTarget = path.resolve(target, input);
  if (fs.existsSync(fromTarget)) return fromTarget;
  try {
    return resolveTaskDir(target, input);
  } catch {
    return '';
  }
}

function section(text, heading) {
  const escaped = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`^##\\s+${escaped}[\\t ]*\\r?\\n[\\s\\S]*?(?=\\r?\\n##\\s+|(?![\\s\\S]))`, 'm');
  const m = text.match(re);
  return m ? m[0].trim() : '';
}

function extractNextPrompt(workflowText) {
  const sec = section(workflowText, 'Prompt bước tiếp theo') || section(workflowText, 'Prompt bước tiếp theo');
  if (!sec) return '';
  return sec.replace(/^##\s+(Prompt bước tiếp theo|Prompt bước tiếp theo)\s*/,'').trim();
}

function checklistOpenItems(text) {
  const lines = text.split(/\r?\n/);
  return lines.filter(l => /\|/.test(l) && /(Chưa làm|Đang thực hiện|Bị chặn|Cần review|Cần sửa)/.test(l));
}


async function init() {
  const target = path.resolve(argValue('--target', process.cwd()));
  let agents;
  try {
    agents = await chooseAgentsForInit();
  } catch (err) {
    console.error(err.message || String(err));
    process.exit(1);
  }
  if (!agents.length) {
    console.error('No agent target selected. Use --agents all, or one/more of: codex, claude, cursor, github.');
    process.exit(1);
  }

  if (!fs.existsSync(path.join(kitRoot, 'core', 'adapters'))) {
    console.error('`init` phải chạy từ repo kit (cần core/adapters). Bản fe-kit.mjs trong repo dự án chỉ dùng cho new-task/status/validate-*.');
    process.exit(1);
  }

  // --- File do kit quản lý: ghi đè ---
  copyFile(path.join(kitRoot, 'QUICKSTART.md'), path.join(target, 'docs', 'frontend-delivery-quickstart.md'));
  // Repo dự án không có node_modules của kit nên phải nhận bản bundle standalone.
  const standaloneCli = path.join(kitRoot, 'standalone', 'fe-kit.mjs');
  if (!fs.existsSync(standaloneCli)) {
    console.error('Thiếu standalone/fe-kit.mjs. Chạy `npm run build` trong repo kit trước khi init.');
    process.exit(1);
  }
  copyFile(standaloneCli, path.join(target, 'bin', 'fe-kit.mjs'));
  copyDir(path.join(kitRoot, 'rules'), path.join(target, '.frontend-delivery', 'rules'));
  copyDir(path.join(kitRoot, 'templates'), path.join(target, '.frontend-delivery', 'templates'));
  copyFile(path.join(kitRoot, 'docs', 'frontend-tasks', 'README.md'), path.join(target, 'docs', 'frontend-tasks', 'README.md'));

  // --- File của team: chỉ tạo khi chưa có ---
  copyDirIfMissing(path.join(kitRoot, 'docs', 'frontend-context'), path.join(target, 'docs', 'frontend-context'));
  const oldRuleContext = path.join(target, 'docs', 'frontend-context', 'frontend-rule-context.md');
  if (fs.existsSync(oldRuleContext)) fs.unlinkSync(oldRuleContext);
  copyFileIfMissing(path.join(kitRoot, 'standard.yaml'), path.join(target, '.frontend-delivery', 'standard.yaml'));
  ensureRunLogMergeUnion(target);

  if (agents.includes('codex')) {
    upsertManagedBlock(path.join(target, 'AGENTS.md'), read(adapterPath('codex', 'AGENTS.md')));
    copyDir(adapterPath('codex', '.codex'), path.join(target, '.codex'));
    writeCodexPrompts(target);
  }
  if (agents.includes('claude')) {
    // Plugin `fe` mang commands/agents/skill/hooks/MCP. Repo dự án chỉ cần
    // CLAUDE.md, rule theo path (plugin không ship được) và khai báo bật plugin.
    upsertManagedBlock(path.join(target, 'CLAUDE.md'), read(adapterPath('claude', 'CLAUDE.md')));
    copyDir(adapterPath('claude', '.claude', 'rules'), path.join(target, '.claude', 'rules'));
    if (enableClaudePlugin(target)) console.log(`Đã bật plugin ${PLUGIN_ID} trong .claude/settings.json (commit file này để cả team cùng dùng).`);
    const legacy = legacyClaudeCopies(target);
    if (legacy.length) {
      console.warn('Phát hiện bản copy v1.x sẽ trùng với plugin, hãy xoá:');
      for (const rel of legacy) console.warn('  - ' + rel);
    }
  }
  if (agents.includes('cursor')) copyDir(adapterPath('cursor', '.cursor'), path.join(target, '.cursor'));
  if (agents.includes('github')) copyDir(adapterPath('github', '.github'), path.join(target, '.github'));

  writeInstallManifest(target, agents);
  console.log('Frontend Delivery Agent Kit initialized in ' + target);
  console.log('Installed agent targets: ' + agentList(agents));
  console.log('Next: edit docs/frontend-context/*.md and inspect .frontend-delivery/rules/, then run: node bin/fe-kit.mjs new-task FE-123-name --target <repo>');
}

function doctor() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const strict = args.includes('--strict');
  let agents;
  try {
    agents = agentsForDoctor(target);
  } catch (err) {
    console.error(err.message || String(err));
    process.exit(1);
  }
  const commonRequired = [
    'bin/fe-kit.mjs',
    'docs/frontend-context/project-source-context.md','docs/frontend-context/feature-source-context.md','docs/frontend-context/design-context.md',
    ...allRuleFiles().map(rule => '.frontend-delivery/rules/' + rule),
    '.frontend-delivery/templates/tracking/workflow-status.md',
    '.frontend-delivery/templates/task.md','.frontend-delivery/templates/planning/implementation-plan.md','.frontend-delivery/templates/planning/build-checklist.md','.frontend-delivery/templates/planning/questions.md',
    '.frontend-delivery/standard.yaml','.frontend-delivery/install.json'
  ];
  const requiredByAgent = {
    codex: ['AGENTS.md','.codex/README.md','.codex/rules/frontend-delivery.md','.codex/prompts/plan.md','.codex/prompts/quick.md','.codex/prompts/build.md','.codex/prompts/figma-extract.md','.codex/prompts/figma-review.md','.codex/prompts/review.md'],
    claude: ['CLAUDE.md','.claude/rules/frontend-delivery.md','.claude/rules/frontend/task-folders.md','.claude/rules/frontend/source-code.md'],
    cursor: ['.cursor/rules/frontend-delivery-standard.mdc','.cursor/rules/frontend-delivery-task.mdc','.cursor/rules/frontend-delivery-code.mdc'],
    github: ['.github/copilot-instructions.md','.github/instructions/frontend-task.instructions.md','.github/instructions/frontend-review.instructions.md','.github/pull_request_template.md']
  };
  const required = [...commonRequired, ...agents.flatMap(a => requiredByAgent[a] || [])];
  let ok = true;
  const alternatives = {
    '.frontend-delivery/templates/tracking/workflow-status.md': ['templates/tracking/workflow-status.md'],
    '.frontend-delivery/standard.yaml': ['standard.yaml'],
    '.github/instructions/frontend-task.instructions.md': ['.github/frontend-task.instructions.md'],
    '.github/instructions/frontend-review.instructions.md': ['.github/frontend-review.instructions.md']
  };
  console.log('Checking installed agent targets: ' + agentList(agents));
  for (const rel of required) {
    let present = fs.existsSync(path.join(target, rel));
    for (const alt of alternatives[rel] || []) {
      if (!present && fs.existsSync(path.join(target, alt))) present = true;
    }
    console.log((present ? 'OK' : 'MISSING') + ' ' + rel);
    if (!present) ok = false;
  }
  if (agents.includes('claude')) {
    // Với Claude Code, commands/agents/skill đến từ plugin chứ không nằm trong repo.
    const enabled = claudePluginEnabled(target);
    // Không tính là lỗi: plugin có thể được cài ở scope user, ngoài repo.
    console.log(
      enabled
        ? `OK plugin ${PLUGIN_ID} bật trong .claude/settings*.json`
        : `LƯU Ý plugin ${PLUGIN_ID} chưa bật ở scope project; cần \`claude plugin install ${PLUGIN_ID}\` (scope user) hoặc chạy lại init`
    );
    for (const rel of legacyClaudeCopies(target)) {
      console.log('TRÙNG ' + rel + ' — bản copy v1.x, xoá đi để không trùng với plugin');
      ok = false;
    }
  }
  if (!ok) {
    console.error('Doctor failed. Run: node bin/fe-kit.mjs init --target <repo> --agents <all|codex,claude,cursor,github>');
    process.exit(strict ? 1 : 0);
  }
  console.log('Doctor passed. Selected Frontend Delivery Kit agent files are present.');
  console.log(`Tiếp theo: node bin/fe-kit.mjs new-task FE-123-task-name --target ${target}`);
}

function newTask() {
  const slug = args[1];
  if (!slug) {
    console.error('Usage: node bin/fe-kit.mjs new-task FE-123-task-name [--target repo]');
    process.exit(1);
  }
  if (args.includes('--layout')) {
    console.error('Không còn hỗ trợ --layout. new-task luôn dùng standard task structure.');
    process.exit(1);
  }
  const target = path.resolve(argValue('--target', process.cwd()));
  // Template: override của repo đích nếu có, nếu không thì bản của kit. Logic
  // tạo file dùng chung với MCP tool `fe_new_task` (packages/validators/src/scaffold.mjs).
  const templatesDir = [
    path.join(target, '.frontend-delivery', 'templates'),
    path.join(kitRoot, 'templates'),
    path.join(kitRoot, '.frontend-delivery', 'templates'),
  ].find((dir) => fs.existsSync(dir));
  if (!templatesDir) {
    console.error('Không tìm thấy thư mục templates (.frontend-delivery/templates). Chạy fe-kit init trước.');
    process.exit(1);
  }
  const scaffold = scaffoldTask({ workspaceRoot: target, name: slug, templatesDir });
  if (!scaffold.ok) {
    console.error(scaffold.error);
    process.exit(1);
  }
  const taskDir = scaffold.taskDir;
  const taskRel = scaffold.taskRef;
  console.log(`Created task: ${taskDir}`);
  console.log('Created standard task files: task.md, planning/implementation-plan.md, planning/build-checklist.md, planning/questions.md, tracking/workflow-status.md, output/figma-reference-screenshots/.gitkeep');

  // Đọc next_prompt thật từ workflow-status.md vừa ghi, không hardcode —
  // tránh lệch nếu default template thay đổi sau này.
  const workflowText = read(path.join(taskDir, 'tracking', 'workflow-status.md'));
  const realNextPrompt = extractNextPrompt(workflowText);
  console.log(`\nTiếp theo: ${realNextPrompt || `FE plan ${taskRel}`}`);
  console.log('Nếu SRS có req/res/DTO/error context thì SRS là source of truth cho API.');
  console.log(`Task nhỏ, rủi ro thấp, không cần re-plan/input-sync/Figma? Dùng thay: FE quick ${taskRel}`);
  console.log(`Workflow status: ${path.join(taskDir, 'tracking', 'workflow-status.md')}`);
}

function status() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const taskDir = resolveTask(taskArg(), target);
  if (!taskDir || !exists(taskDir)) { console.error('Task folder not found.'); process.exit(1); }
  const workflow = read(path.join(taskDir, 'tracking', 'workflow-status.md'));
  const checklist = read(path.join(taskDir, 'planning', 'build-checklist.md'));
  console.log(`# Trạng thái task: ${path.basename(taskDir)}\n`);
  if (workflow) {
    const fm = parseFrontMatter(workflow);
    if (fm.hasFrontMatter) {
      console.log('## YAML status');
      for (const k of ['status','layout','current_mode','step_status','blocker','srs_required','srs_trace_matrix_status','api_contract_mapping_status','questions_status','blocking_questions_open','questions_resolution_gate_status','input_sync_required','figma_required','figma_gate_status','token_budget_status','scope_diff_status','command_evidence_status','review_status','review_report_status','review_bug_status','critical_issues_open','high_issues_open','medium_issues_open','low_issues_open','bugfix_required','pr_status','build_ready','next_mode','human_override']) {
        if (Object.prototype.hasOwnProperty.call(fm.data, k)) console.log(`${k}: ${fm.data[k]}`);
      }
      console.log('');
    }
    const snap = section(workflow, 'Snapshot') || section(workflow, 'Current Step') || workflow.split('\n').slice(0,30).join('\n');
    console.log(snap.trim());
  } else console.log('Thiếu tracking/workflow-status.md');
  const questionsText = read(path.join(taskDir, 'planning', 'questions.md'));
  const derivedBlocking = countOpenBlockingQuestions(questionsText);
  console.log(`\nCâu hỏi blocking đang mở (đếm từ questions.md): ${derivedBlocking}`);
  const openChecklist = checklistOpenItems(checklist);
  console.log(`\nChecklist chưa xong: ${openChecklist.length}`);
  if (openChecklist.length) console.log(openChecklist.slice(0,10).join('\n'));
  const prompt = extractNextPrompt(workflow);
  console.log(`\nPrompt bước tiếp theo: ${prompt ? 'Có trong tracking/workflow-status.md' : 'Chưa có'}`);
}

function next() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const taskDir = resolveTask(taskArg(), target);
  if (!taskDir || !exists(taskDir)) { console.error('Task folder not found.'); process.exit(1); }
  const prompt = extractNextPrompt(read(path.join(taskDir, 'tracking', 'workflow-status.md')));
  if (!prompt) { console.error('Không tìm thấy Prompt bước tiếp theo trong tracking/workflow-status.md'); process.exit(1); }
  console.log(prompt);
}


// Mọi gate nằm trong packages/validators; CLI chỉ đọc tham số và in kết quả.

/** Lệnh check-* → [gate, thông báo khi gate tự bỏ qua vì không áp dụng]. */
const CHECKS = {
  'check-srs-reference': [validateSrsReference],
  'check-questions-routing': [validateQuestionsRouting],
  'check-plan-architecture': [validatePlanArchitecture],
  'check-plan-checklist-sync': [validatePlanChecklistSync],
  'check-input-sync-report': [validateInputSyncReport, 'check-input-sync-report skipped: no input sync report required.'],
  'check-figma-evidence': [validateFigmaEvidence, 'check-figma-evidence skipped: figma_required=false/not required.'],
  'check-asset-gate': [validateAssetGate, 'check-asset-gate skipped: no Figma summary and figma_required=false/not required.'],
};

function checkCommand(name) {
  const [check, skippedMessage] = CHECKS[name];
  const target = path.resolve(argValue('--target', process.cwd()));
  const taskDir = resolveTask(taskArg(), target);
  if (!taskDir || !exists(taskDir)) { console.error('Task folder not found.'); process.exit(1); }
  const result = check(taskDir);
  if (!result.ok) {
    for (const err of result.errors) console.error(err);
    process.exit(1);
  }
  console.log(result.skipped ? skippedMessage : `${name} passed.`);
}

/** Scope diff tính từ git. `undefined` khi không tính được hoặc bị tắt bằng --no-scope. */
function scopeForTask(taskDir, target) {
  if (args.includes('--no-scope')) return undefined;
  const base = argValueFlexible('--base', '') || detectBaseRef(target);
  return scopeDiffForTask(taskDir, { repoRoot: target, base }) || undefined;
}

function printWarnings(result) {
  for (const w of result.warnings || []) console.warn('Cảnh báo: ' + w);
}
function nextStepHint(taskDir) {
  const workflowText = read(path.join(taskDir, 'tracking', 'workflow-status.md'));
  const prompt = extractNextPrompt(workflowText);
  return prompt ? `Tiếp theo: ${prompt}` : 'Tiếp theo: chưa xác định được — kiểm tra mục "Prompt bước tiếp theo" trong tracking/workflow-status.md.';
}

function validateWorkflowLean() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const taskDir = resolveTask(taskArg(), target);
  if (!taskDir || !exists(taskDir)) { console.error('Task folder not found.'); process.exit(1); }
  // Mặc định giống MCP fe_validate_workflow: chỉ task ở review/test/pr-ready mới
  // đối chiếu scope với git (working tree lúc plan có thể có thay đổi không liên
  // quan). --scope: luôn tính ở mọi mode. --no-scope: không tính.
  let result;
  if (args.includes('--no-scope')) result = validateWorkflow(taskDir);
  else if (args.includes('--scope')) result = validateWorkflow(taskDir, { scope: scopeForTask(taskDir, target) });
  else {
    result = validateWorkflowAtGate(taskDir, { repoRoot: target, base: argValueFlexible('--base', '') || undefined });
    if (result.scopeSource === 'git') console.log(`Scope: tính từ git (base: ${result.base || 'chỉ thay đổi chưa commit'}).`);
  }
  printWarnings(result);
  const errors = [...new Set(result.errors)];
  const codes = codesOf(result);
  const md = walk(taskDir).filter(p => p.endsWith('.md'));
  for (const f of md) {
    const rel = path.relative(taskDir, f).replaceAll('\\','/');
    if (rel !== 'tracking/workflow-status.md' && /^##\s+Prompt bước tiếp theo/im.test(read(f))) {
      errors.push('Prompt bước tiếp theo không được nằm trong: ' + rel);
      codes.push('NEXT_PROMPT_OUTSIDE_STATUS');
    }
  }
  logValidate(taskDir, 'validate-workflow', errors.length === 0, codes);
  if (errors.length) { for (const e of errors) console.error(e); process.exit(1); }
  console.log('validate-workflow passed.');
  console.log(nextStepHint(taskDir));
}
function validateTaskLean() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const taskDir = resolveTask(taskArg(), target);
  if (!taskDir || !exists(taskDir)) { console.error('Task folder not found.'); process.exit(1); }
  let ok = true;
  for (const rel of REQUIRED_TASK_FILES) {
    const present = exists(path.join(taskDir, rel));
    console.log(`${present ? 'OK' : 'MISSING'} ${rel}`);
    if (!present) ok = false;
  }
  const filesOk = ok;
  const result = validateWorkflow(taskDir);
  printWarnings(result);
  if (!result.ok) { ok = false; for (const e of result.errors) console.error(e); }
  logValidate(taskDir, 'validate-task', ok, [...(filesOk ? [] : ['TASK_FILE_MISSING']), ...codesOf(result)]);
  if (!ok) process.exit(1);
  console.log('validate-task passed.');
  console.log(nextStepHint(taskDir));
}
/**
 * PR không gắn task: file source đã đổi mà không task nào khai trong plan.
 * Mức xử lý theo `require_task_for_source` trong .frontend-delivery/standard.yaml.
 */
function validateOrphans() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const { config, warnings } = loadProjectConfig(target);
  for (const w of warnings) console.warn('Cảnh báo: ' + w);
  if (config.require_task_for_source === 'off') {
    console.log('validate-pr --orphans: bỏ qua (require_task_for_source: off).');
    return;
  }
  const base = argValueFlexible('--base', '') || detectBaseRef(target);
  const res = findUntrackedSourceChanges(target, { base, sourcePaths: config.source_paths });
  if (!res) {
    console.warn('Cảnh báo: không tính được thay đổi từ git; bỏ qua validate-pr --orphans.');
    return;
  }
  if (!res.files.length) {
    console.log('validate-pr --orphans passed: mọi file source đã đổi đều thuộc plan của một task.');
    return;
  }
  const message =
    `${res.files.length} file source đã đổi nhưng không task nào khai trong "File sẽ tạo / cập nhật": ${res.files.join(', ')}. ` +
    'Tạo task (fe-kit new-task) hoặc thêm file vào plan của task liên quan.';
  if (config.require_task_for_source === 'error') {
    console.error(message);
    process.exit(1);
  }
  console.warn((process.env.GITHUB_ACTIONS ? '::warning::' : 'Cảnh báo: ') + message);
}

function validatePrLean() {
  if (args.includes('--orphans')) return validateOrphans();
  const target = path.resolve(argValue('--target', process.cwd()));
  const taskDir = resolveTask(taskArg(), target);
  if (!taskDir || !exists(taskDir)) { console.error('Task folder not found.'); process.exit(1); }
  // Cùng một hàm với core/scripts/validate-pr.mjs. Trước v2.0.0 CLI tự kiểm
  // bằng parser regex và từ chối `command_evidence_status: passed` mà script kia chấp nhận.
  const scope = scopeForTask(taskDir, target);
  if (!scope) console.warn('Cảnh báo: không tính được scope diff từ git; dùng scope_diff_status tự khai.');
  const result = validatePr(taskDir, { scope });
  printWarnings(result);
  logValidate(taskDir, 'validate-pr', result.ok, codesOf(result));
  if (!result.ok) { for (const e of [...new Set(result.errors)]) console.error(e); process.exit(1); }
  console.log('validate-pr passed.');
  console.log(nextStepHint(taskDir));
}

// --- Run-log, mode begin/end cho adapter không có hook (Codex, Cursor, Copilot) ---

function cliActor() {
  return argValueFlexible('--actor', '') || process.env.FE_KIT_ACTOR || 'cli';
}

/** Ghi run-log từ CLI. Bỏ qua khi có --no-log, hoặc trên CI vì checkout bị bỏ đi sau job. */
function logCli(taskDir, record) {
  if (args.includes('--no-log') || String(process.env.CI || '').toLowerCase() === 'true') return;
  appendRunLog(taskDir, { source: 'cli', actor: cliActor(), kit: readKitVersion(), ...record });
}

function logValidate(taskDir, check, ok, codes) {
  logCli(taskDir, { event: 'validate', check, outcome: ok ? 'ok' : 'failed', codes: [...new Set(codes)] });
}

/** Lần `mode begin` gần nhất của mode này và số lần `mode end` không đạt sau đó. */
function lastModeRun(taskDir, command) {
  const { records } = readRunLog(taskDir);
  let start = -1;
  records.forEach((r, i) => {
    if (r.event === 'mode_start' && r.mode === command) start = i;
  });
  if (start < 0) return { startedAt: undefined, failedEnds: 0 };
  const failedEnds = records
    .slice(start + 1)
    .filter((r) => r.event === 'mode_end' && r.mode === command && r.outcome === 'failed').length;
  return { startedAt: Date.parse(records[start].ts), failedEnds };
}

function rulesDirFor(target) {
  const project = path.join(target, '.frontend-delivery', 'rules');
  if (fs.existsSync(project)) return { dir: project, label: '.frontend-delivery/rules của repo' };
  return { dir: path.join(kitRoot, 'rules'), label: 'kit' };
}

function modeCommand() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const [, action, taskInput, modeInput] = args;
  const command = normalizeCommand(modeInput || '');
  if (!['begin', 'end'].includes(action) || !taskInput || !command) {
    console.error(`Dùng: fe-kit mode begin|end <task> <mode> [--target repo] [--actor codex|cursor|copilot] [--no-log]\nMode hợp lệ: ${COMMANDS.join(', ')}.`);
    process.exit(1);
  }
  const taskDir = resolveTask(taskInput, target);
  const taskRef = relativePosix(target, taskDir) || taskInput;
  if (action === 'begin') modeBegin({ target, taskDir, taskRef, command });
  else modeEnd({ target, taskDir, taskRef, command });
}

/** Như MCP fe_begin_mode: verdict gate, artifact bắt buộc, nguyên văn rule của mode. */
function modeBegin({ target, taskDir, taskRef, command }) {
  const rules = rulesDirFor(target);
  const briefing = modeBriefing({
    taskDir,
    taskRef,
    command,
    rulesDir: rules.dir,
    rulesLabel: rules.label,
    newTaskHint: `Chạy node bin/fe-kit.mjs new-task ${path.basename(taskDir)} để tạo task từ template, rồi chạy lại: node bin/fe-kit.mjs mode begin ${taskRef} ${command}`,
    finishHint: `Trước khi kết thúc: cập nhật tracking/workflow-status.md rồi chạy node bin/fe-kit.mjs mode end ${taskRef} ${command}.`,
    workspaceRoot: target,
  });
  console.log(briefing.text);
  if (briefing.entry) {
    logCli(taskDir, { event: 'mode_start', mode: command });
    if (!briefing.ok) logCli(taskDir, { event: 'entry_blocked', mode: command, codes: briefing.entry.reasonCodes });
  }
  process.exit(briefing.ok ? 0 : 1);
}

/** Cùng gate kết thúc mode với hook của Claude Code (`evaluateModeCompletion`). */
function modeEnd({ target, taskDir, taskRef, command }) {
  const { startedAt, failedEnds } = lastModeRun(taskDir, command);
  const result = evaluateModeCompletion({
    taskDir,
    taskRef,
    command,
    startedAt,
    repoRoot: target,
    base: argValueFlexible('--base', '') || undefined,
  });
  logCli(taskDir, {
    event: 'mode_end',
    mode: command,
    outcome: result.ok ? 'pass' : 'failed',
    attempt: failedEnds + 1,
    duration_ms: startedAt ? Math.max(0, Date.now() - startedAt) : undefined,
    codes: codesOf(result),
  });
  if (!result.ok) {
    console.error(`mode end: FE ${command} cho ${taskRef} chưa đạt gate kết thúc mode:`);
    for (const e of result.errors) console.error('- ' + e);
    process.exit(1);
  }
  console.log(`mode end: PASSED (FE ${command}${result.refused ? ', mode bị gate từ chối và đã route đúng' : ''}).`);
  console.log(nextStepHint(taskDir));
}

function report() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const task = args[1] && !args[1].startsWith('--') ? resolveTask(args[1], target) : undefined;
  const result = buildReport({ repoRoot: target, task, since: argValueFlexible('--since', '') || undefined });
  if (args.includes('--json')) console.log(JSON.stringify(result, null, 2));
  else process.stdout.write(renderReport(result));
}

/**
 * `retro [--since D] [--date D] [--json] [--write]`: số liệu retro của repo.
 * `retro check <thư-mục>`: kiểm thư mục retro. `retro export <thư-mục>`: đề xuất upstream đã duyệt.
 */
function retro() {
  const target = path.resolve(argValue('--target', process.cwd()));
  const action = args[1] && !args[1].startsWith('--') ? args[1] : '';
  if (action === 'check' || action === 'export') {
    const dir = args[2] ? path.resolve(target, args[2]) : '';
    if (!dir || !exists(dir)) { console.error(`Dùng: fe-kit retro ${action} <${RETRO_ROOT}/YYYY-MM-DD>`); process.exit(1); }
    if (action === 'export') {
      const text = exportUpstreamProposals(read(path.join(dir, 'proposals.md')));
      console.log(text || 'Không có đề xuất upstream nào đã duyệt.');
      return;
    }
    const res = validateRetroFolder(dir);
    for (const w of res.warnings) console.warn('Cảnh báo: ' + w);
    if (!res.ok) { for (const e of res.errors) console.error(e); process.exit(1); }
    console.log('retro check passed.');
    return;
  }
  if (action) { console.error('Dùng: fe-kit retro [--since YYYY-MM-DD] [--date YYYY-MM-DD] [--json] [--write] | retro check <thư-mục> | retro export <thư-mục>'); process.exit(1); }
  const data = buildRetroData(target, { since: argValueFlexible('--since', '') || undefined });
  if (args.includes('--write')) {
    const day = argValueFlexible('--date', '') || new Date().toISOString().slice(0, 10);
    const dir = path.join(target, RETRO_ROOT, day);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'retro-data.json'), JSON.stringify(data, null, 2) + '\n');
    console.error(`Đã ghi ${RETRO_ROOT}/${day}/retro-data.json`);
  }
  if (args.includes('--json')) console.log(JSON.stringify(data, null, 2));
  else process.stdout.write(renderRetroSummary(data));
}

function help() {
  console.log(`Frontend Delivery Agent Kit CLI v${readKitVersion()}\nRules folder + plan input ledger + blocking question input-sync gate + scope diff tính từ git + command evidence trước PR.\n\nCommands:\n  # Agent prompt mode: FE quick <task> is available for small, low-risk localized changes. FE figma-review <task> is available for UI/Figma visual review.\n  init [--target repo] [--agents all|codex,claude,cursor,github]\n                                      Install selected agent adapters into repo. In a TTY, prompts for agent selection.\n  doctor [--target repo] [--strict] [--agents ...]\n                                      Check kit installation for selected/installed agents\n  new-task <slug> [--target repo]       Create standard FE task folder\n  status <task> [--target repo]         Show current step, blockers, checklist summary\n  next <task> [--target repo]           Print Prompt bước tiếp theo from workflow-status.md\n  validate-task <task> [--target repo]  Validate standard task structure and workflow rules\n  validate-pr <task> [--target repo] [--base ref] [--no-scope]\n                                      Validate PR readiness; so git diff với bảng file trong plan\n  validate-pr --orphans [--target repo] [--base ref]\n                                      File source đã đổi mà không task nào khai trong plan\n                                      (mức: require_task_for_source trong .frontend-delivery/standard.yaml)\n  validate-workflow <task> [--target] [--base <ref>] [--scope|--no-scope]\n                                      Validate SRS/questions/plan/checklist/Figma gates\n                                      (review/test/pr-ready: scope from git by default)\n  mode begin <task> <mode> [--target] [--actor <tool>]\n                                      Gate lúc vào mode + rule của mode (cho Codex/Cursor/Copilot)\n  mode end <task> <mode> [--target] [--base <ref>] [--actor <tool>]\n                                      Gate kết thúc mode, giống hook của Claude Code\n  retro [--since YYYY-MM-DD] [--date YYYY-MM-DD] [--json] [--write]\n                                      Số liệu retro (run-log + bug theo nhóm/nguyên nhân gốc)\n  retro check <dir> | retro export <dir>\n                                      Kiểm thư mục retro / xuất đề xuất upstream đã duyệt\n  report [<task>] [--target] [--since YYYY-MM-DD] [--json]\n                                      Tổng hợp tracking/run-log.jsonl của các task\n                                      (validate-*/mode ghi run-log; tắt bằng --no-log, CI=true tự tắt)\n  check-srs-reference <task> [--target] Validate task.md SRS/API maps\n  check-questions-routing <task> [--target] Validate questions.md routing sections/owners\n  check-plan-architecture <task> [--target] Validate frontend logic architecture plan sections\n  check-plan-checklist-sync <task> [--target] Validate checklist mirrors plan file/hook/store decisions\n  check-input-sync-report <task> [--target] Validate tracking/input-sync-report.md when input sync is active\n  check-figma-evidence <task> [--target] Validate Figma summary, screenshots, and MCP/API evidence\n  check-asset-gate <task> [--target]     Validate embedded Asset Extraction Log\n`);
}


if (command === 'init') await init();
else if (command === 'doctor') doctor();
else if (command === 'new-task') newTask();
else if (command === 'status') status();
else if (command === 'next') next();
else if (command === 'validate-task') validateTaskLean();
else if (command === 'validate-pr') validatePrLean();
else if (command === 'validate-workflow') validateWorkflowLean();
else if (command === 'mode') modeCommand();
else if (command === 'report') report();
else if (command === 'retro') retro();
else if (CHECKS[command]) checkCommand(command);
else help();
